#include <stdbool.h>
#include <stdlib.h>

struct Graph {
    int V, E, cnt;
    int *head;      /* head[u] = index of first edge out of u, or -1 */
    int *to, *next; /* edge i goes to to[i]; next[i] chains the list */
};

struct Graph *graph_new(int V, int maxE) {
    struct Graph *g = malloc(sizeof *g);
    g->V = V; g->E = maxE; g->cnt = 0;
    g->head = malloc(V * sizeof *g->head);
    g->to = malloc(maxE * sizeof *g->to);
    g->next = malloc(maxE * sizeof *g->next);
    for (int i = 0; i < V; i++) g->head[i] = -1;
    return g;
}

void add_edge(struct Graph *g, int u, int v) {   /* directed u -> v */
    g->to[g->cnt] = v;
    g->next[g->cnt] = g->head[u];
    g->head[u] = g->cnt++;
}

void bfs(const struct Graph *g, int s, int *dist, int *parent) {
    int *q = malloc(g->V * sizeof *q);
    int qh = 0, qt = 0;
    for (int i = 0; i < g->V; i++) { dist[i] = -1; parent[i] = -1; }
    dist[s] = 0;
    q[qt++] = s;
    while (qh < qt) {
        int u = q[qh++];
        for (int e = g->head[u]; e != -1; e = g->next[e]) {
            int v = g->to[e];
            if (dist[v] == -1) {          /* unvisited */
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q[qt++] = v;
            }
        }
    }
    free(q);
}

static void dfs_rec(const struct Graph *g, int u, bool *seen) {
    seen[u] = true;
    for (int e = g->head[u]; e != -1; e = g->next[e]) {
        int v = g->to[e];
        if (!seen[v]) dfs_rec(g, v, seen);
    }
}

void dfs_iter(const struct Graph *g, int s, bool *seen) {
    int *st = malloc((g->cnt + 1) * sizeof *st), top = 0;
    st[top++] = s;
    while (top) {
        int u = st[--top];
        if (seen[u]) continue;
        seen[u] = true;
        for (int e = g->head[u]; e != -1; e = g->next[e])
            if (!seen[g->to[e]]) st[top++] = g->to[e]; /* may push duplicates */
    }
    free(st);
}

#define N 5
int m[N][N];                          /* zero-initialized as a global */

void add_undirected(int u, int v) { m[u][v] = m[v][u] = 1; }
int  has_edge(int u, int v)       { return m[u][v]; }

/* directed cycle: state 0 = new, 1 = on stack, 2 = done */
static bool has_cycle(const struct Graph *g, int u, int *state) {
    state[u] = 1;
    for (int e = g->head[u]; e != -1; e = g->next[e]) {
        int v = g->to[e];
        if (state[v] == 1) return true;
        if (state[v] == 0 && has_cycle(g, v, state)) return true;
    }
    state[u] = 2;
    return false;
}

static const int dr[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};

/* shortest steps in a grid of 0 (open) and 1 (wall), or -1 */
int grid_bfs(int R, int C, const int *g, int sr, int sc, int tr, int tc) {
    int *dist = malloc(R * C * sizeof *dist), *q = malloc(R * C * sizeof *q);
    int qh = 0, qt = 0, ans = -1;
    for (int i = 0; i < R * C; i++) dist[i] = -1;
    dist[sr * C + sc] = 0; q[qt++] = sr * C + sc;
    while (qh < qt) {
        int u = q[qh++], r = u / C, c = u % C;
        if (r == tr && c == tc) { ans = dist[u]; break; }
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (g[nr * C + nc] || dist[nr * C + nc] != -1) continue;
            dist[nr * C + nc] = dist[u] + 1; q[qt++] = nr * C + nc;
        }
    }
    free(dist); free(q);
    return ans;
}
